import 'dart:convert';
import 'package:flutter/foundation.dart';
import '../state/app_session_state.dart';
import 'web_face_bridge.dart';

/// Multilingual Neural Studio Voice Assistant (KK: Daulet, RU: Svetlana, EN: Emma).
/// Automatically adapts to the active language selected on the home screen (appState.lang).
class KazakhVoiceAudio {
  static const Map<String, String> _b64Audio = <String, String>{
    'awake_confirmed': '',
    'drowsiness_alert': '',
    'en_awake_confirmed': '',
    'en_drowsiness_alert': '',
    'en_head_droop_alert': '',
    'en_nav_arrived': '',
    'en_nav_route_built': '',
    'en_nav_straight': '',
    'en_nav_turn_left': '',
    'en_nav_turn_right': '',
    'en_yawn_alert': '',
    'head_droop_alert': '',
    'kk_awake_confirmed': '',
    'kk_drowsiness_alert': '',
    'kk_head_droop_alert': '',
    'kk_nav_arrived': '',
    'kk_nav_route_built': '',
    'kk_nav_straight': '',
    'kk_nav_turn_left': '',
    'kk_nav_turn_right': '',
    'kk_yawn_alert': '',
    'nav_arrived': '',
    'nav_route_built': '',
    'nav_straight': '',
    'nav_turn_left': '',
    'nav_turn_right': '',
    'ru_awake_confirmed': '',
    'ru_drowsiness_alert': '',
    'ru_head_droop_alert': '',
    'ru_nav_arrived': '',
    'ru_nav_route_built': '',
    'ru_nav_straight': '',
    'ru_nav_turn_left': '',
    'ru_nav_turn_right': '',
    'ru_yawn_alert': '',
    'yawn_alert': '',
  };

  static Uint8List getBytes(String key) {
    final String currentLang = appState.lang;
    final String fullKey = '${currentLang}_$key';
    final String? b64 = _b64Audio[fullKey] ?? _b64Audio[key] ?? _b64Audio['kk_$key'];
    if (b64 == null) return Uint8List(0);
    return base64Decode(b64);
  }

  static void playAlert(String key) {
    final String currentLang = appState.lang;
    final String fullKey = '${currentLang}_$key';
    if (kIsWeb) {
      WebFaceBridge.playKazakhVoice(fullKey);
    }
  }

  // Safety Alerts (Automatic multi-language adaptation)
  static void playDrowsinessAlert() => playAlert('drowsiness_alert');
  static void playYawnAlert() => playAlert('yawn_alert');
  static void playHeadDroopAlert() => playAlert('head_droop_alert');
  static void playAwakeConfirmed() => playAlert('awake_confirmed');

  // Navigation Prompts (Automatic multi-language adaptation)
  static void playNavRouteBuilt() => playAlert('nav_route_built');
  static void playNavTurnRight() => playAlert('nav_turn_right');
  static void playNavTurnLeft() => playAlert('nav_turn_left');
  static void playNavStraight() => playAlert('nav_straight');
  static void playNavArrived() => playAlert('nav_arrived');
}
